<?php
require_once __DIR__ . '/db.php';
try{$pdo=db();if(($_SERVER['REQUEST_METHOD']??'')==='GET'){$no=trim((string)($_GET['order_no']??''));if($no==='')api_json(400,['ok'=>false,'error'=>'order_no is required']);$q=$pdo->prepare('SELECT order_no,status,payment_method,subtotal,discount,shipping,total,customer_name,phone,email,address,city,notes,created_at FROM orders WHERE order_no=?');$q->execute([$no]);$order=$q->fetch();if(!$order)api_json(404,['ok'=>false,'error'=>'Order not found']);$q=$pdo->prepare('SELECT slug,name,price,qty FROM order_items WHERE order_no=?');$q->execute([$no]);$order['items']=$q->fetchAll();api_json(200,['ok'=>true,'order'=>$order]);}
api_method('POST');$in=api_input();$customer=$in['customer']??[];$items=$in['items']??[];if(!is_array($customer)||!is_array($items)||!count($items))api_json(422,['ok'=>false,'error'=>'Your cart is empty']);$name=trim((string)($customer['name']??''));$phone=trim((string)($customer['phone']??''));$email=trim((string)($customer['email']??''));$address=trim((string)($customer['address']??''));$city=trim((string)($customer['city']??''));$notes=trim((string)($customer['notes']??''));if($name===''||!preg_match('/^03\d{9}$/',$phone)||$address===''||$city==='')api_json(422,['ok'=>false,'error'=>'Name, valid phone, address, and city are required']);if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))api_json(422,['ok'=>false,'error'=>'Invalid email address']);$method=(string)($in['payment_method']??'cod');if(!in_array($method,['cod','jazzcash','easypaisa','meezan'],true))api_json(422,['ok'=>false,'error'=>'Invalid payment method']);if($method==='meezan'&&app_env('HBL_ENABLED','false')!=='true')api_json(403,['ok'=>false,'error'=>'Meezan card checkout is disabled']);$catalog=[];foreach($pdo->query('SELECT slug,name,price_pkr FROM products')->fetchAll() as $p)$catalog[$p['slug']]=$p;$normalized=[];$subtotal=0;foreach($items as $item){$slug=(string)($item['slug']??'');if(!isset($catalog[$slug]))continue;$qty=max(1,min(20,(int)($item['qty']??1)));$p=$catalog[$slug];$normalized[]=['slug'=>$slug,'name'=>$p['name'],'price'=>(int)$p['price_pkr'],'qty'=>$qty];$subtotal+=(int)$p['price_pkr']*$qty;}if(!$normalized)api_json(422,['ok'=>false,'error'=>'Your cart is empty']);$discount=0;$coupon=strtoupper(trim((string)($in['coupon']??'')));if($coupon!==''){$q=$pdo->prepare('SELECT percent FROM coupons WHERE code=? AND active=1');$q->execute([$coupon]);$pct=$q->fetchColumn();if($pct!==false)$discount=(int)round($subtotal*(int)$pct/100);}$shipping=$subtotal-$discount>3000?0:250;$total=max(0,$subtotal-$discount+$shipping);$prefix=['jazzcash'=>'JC','easypaisa'=>'EP','meezan'=>'HB'][$method]??'ZB';$orderNo=$prefix.'-'.strtoupper(bin2hex(random_bytes(4)));$status=$method==='cod'?'confirmed':'pending';$pdo->beginTransaction();$q=$pdo->prepare('INSERT INTO orders(order_no,status,payment_method,subtotal,discount,shipping,total,customer_name,phone,email,address,city,notes,gateway_ref,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$orderNo,$status,$method,$subtotal,$discount,$shipping,$total,$name,$phone,$email,$address,$city,$notes,null,gmdate('c')]);$qi=$pdo->prepare('INSERT INTO order_items(order_no,slug,name,price,qty) VALUES(?,?,?,?,?)');foreach($normalized as $i)$qi->execute([$orderNo,$i['slug'],$i['name'],$i['price'],$i['qty']]);$pdo->commit();api_json(201,['ok'=>true,'order_no'=>$orderNo,'total'=>$total,'status'=>$status]);}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();api_json(500,['ok'=>false,'error'=>'Unable to save order']);}
